    [Parameter] public string Name { get; set; }
    [Parameter] public string Email { get; set; }
    [Parameter] public string Message { get; set; }
    [Parameter] public string Subject { get; set; }

    string ErrorMsg = "";
    string SuccessMsg = "";
    bool sent = false;

    protected override Task OnInitializedAsync()
    {
        this.ErrorMsg = "";
        this.SuccessMsg = sent ? "Вашият имейл беше успешно изпратен!" : "";
        return base.OnInitializedAsync();
    }

    private async Task SendAsync()
    {
        if (string.IsNullOrEmpty(Name) ||
           string.IsNullOrEmpty(Email) ||
           string.IsNullOrEmpty(Message) ||
           string.IsNullOrEmpty(Subject))
        {
            ErrorMsg = "Попълнете всички полета преди да изпратите имейл!";
            return;
        }
        else
        {
            EmailModel model = new EmailModel(Email, Name, Subject, Message);
            var response = await emailSender.SendEmailAsync(model);

            if (response.StatusCode == System.Net.HttpStatusCode.Accepted)
            {
                sent = true;
                navigation.NavigateTo("/Contacts", true);   
            }
        }
    }

